  hillName_orchard: ["果园绕行", "Orchard Run"], hillName_cut: ["坡腰近道", "Hillside Cut"],
  hillClue_lantern: ["司机记得先看见坡顶的灯，最后从邮箱下方进站。", "The driver saw the upper lights first and pulled in from below the box."],
  hillClue_summit: ["沿西侧一路爬到 B1，再去数最上排的窗灯。最后从邮箱下方进站。", "Climb the west side all the way to B1, count the windows along the top row and pull in from below the box."],
  hillClue_market: ["先捎上坡脚夜市的那枚戳，再绕回坡顶的窗灯，从邮箱下方收车。", "Call at the lower market stamp before the upper lights. Finish from below the box."],
  hillClue_balcony: ["上山时经过 B2 后，往东去看 C2 的花窗，再爬回最上排。", "On the climb, head east from B2 past the windowbox at C2, then rejoin the top row."],
  hillClue_orchard: ["收信人习惯从北边的果园小径走来。两枚邮戳都要带上。", "The recipient walks in by the orchard path north of the box. Bring both stamps that way."],
  hillClue_cut: ["邮箱西边有条平路。试试盖齐戳后，沿这条路直接进站。", "A level track meets the west side of the box. Reach it with both stamps on board."],
  hillStory_lantern: ["数到第七盏窗灯，你才发现，我一直数的是玻璃里你的倒影。", "At the seventh lit window you caught me counting your reflections in the glass."],
  hillStory_market: ["在坡脚捎了两只还热的橘饼。上坡时你一直把纸袋抱在怀里。", "We picked up two warm orange cakes at the market. You held the paper bag all the way up."],
  hillStory_balcony: ["花窗里那盆天竺葵又开了。你隔着车窗朝它挥了挥手。", "The geranium in the windowbox was blooming again. You waved through the glass."],
  hillStory_orchard: ["穿过果园时，一片橘叶落进你摊开的信纸。合上信封，香气也寄走了。", "An orange leaf fell onto your letter as we crossed the orchard. You folded its scent into the envelope."],
  hillStory_cut: ["抄近道省下的一小段黄昏，刚够我们在站台分完一只橘子。", "The shortcut saved just enough evening for us to share an orange on the platform."],
  hillMode_relaxed: ["沿海原图，随步提示优先带你找到新车票。", "Coastal map with a suggested move toward an unfiled ticket."],
  hillMode_standard: ["同图自由铺线。点车票读线索，也可单步求助。", "Build freely on the coastal map. Read a ticket clue or ask for one move."],
  hillMode_expert: ["山顶版原图，独立铺线。车票线索仍可查阅。", "Use the summit map and ticket clues to plan each move yourself."],
  watchTitle: ["雾班听测", "Fog Watch"], watchShiftType: ["栈桥邮班", "Pier service"], watchOrdinary: ["日常回信", "Regular mail"],
  watchShift: ["交班簿", "Watch roll"], watchSerial: ["雾班 {n}", "Watch {n}"],
  watchAlbumLink: ["去风铃栈桥听一班雾里的回信。", "Take a shift at Wind Chime Pier and listen for the reply."],
  watchOpen: ["回风铃栈桥值雾班", "Take a fog watch at the pier"], watchChoose: ["从哪盏岸灯发光", "Choose a shore lamp"],
  watchN: ["北岸", "North"], watchE: ["东岸", "East"], watchS: ["南岸", "South"], watchW: ["西岸", "West"],
