  deskEmpty: ["试航后，能省工或更早到站的方案会留在这里。", "Log a trial to keep a route that saves crew time or arrives earlier."],
  deskDirect: ["直航", "Direct sailing"], deskFerryAt: ["{a} ↔ {b} 接驳", "{a} ↔ {b} ferry"],
