  deskCompareLabel: ["叠图对照 {score}", "Overlay the {score} run"], deskLoadLabel: ["载入 {score}", "Load the {score} run"],
  deskGhost: ["淡紫虚线是航簿里的路线。", "The lilac dashes trace the logged route."],
